import React, { useState } from "react";
import {
  Button,
  Col,
  Label,
  Container,
  Row,
  FormGroup,
  Input,
  Form,
} from "reactstrap";
import "../Styles/UserRegister.css";

import { useForm } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
import { loginSchemaValidation } from "../Validations/LoginValidation";
import { useNavigate, Link } from "react-router-dom";

// ✅ For form validation using react-hook-form
const UserRegister = () => {
  // State variables
  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [major, setMajor] = useState("");
  const [age, setAge] = useState(0);

  const navigate = useNavigate();

  // Setup react-hook-form + yup
  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm({
    resolver: yupResolver(loginSchemaValidation),
  });

  // Handle submit
  const onSubmit = (data) => {
    try {
      console.log("Form Data", data);
      alert("Student Registered ✅");
      localStorage.setItem("userData", JSON.stringify(data));
      navigate("/user-profile");
    } catch (error) {
      console.log(error);
    }
  };

  return (
    <Container className="reg-page">
      <h1 className="reg-title">
        Create your <span className="accent">account</span>
      </h1>

      <div className="reg-card">
        <p className="reg-sub">Please fill in your details to continue</p>

        <Form onSubmit={handleSubmit(onSubmit)}>
          <Row>
            <Col md={6}>
              <Label>Full Name</Label>
              <Input
                type="text"
                name="fullName"
                placeholder="Your name"
                {...register("fullName", {
                  value: fullName,
                  onChange: (e) => setFullName(e.target.value),
                })}
              />
              <p className="error">{errors.fullName?.message}</p>
            </Col>
          </Row>

          <Row>
            <Col md={6}>
              <Label>Email</Label>
              <Input
                type="email"
                name="email"
                placeholder="you@example.com"
                {...register("email", {
                  value: email,
                  onChange: (e) => setEmail(e.target.value),
                })}
              />
              <p className="error">{errors.email?.message}</p>
            </Col>
          </Row>

          <Row>
            <Col md={6}>
              <Label>Password</Label>
              <Input
                type="password"
                name="password"
                placeholder="********"
                {...register("password", {
                  value: password,
                  onChange: (e) => setPassword(e.target.value),
                })}
              />
              <p className="error">{errors.password?.message}</p>
            </Col>
          </Row>

          <Row>
            <Col md={6}>
              <Label>Major</Label>
              <Input
                type="select"
                name="major"
                {...register("major", {
                  value: major,
                  onChange: (e) => setMajor(e.target.value),
                })}
              >
                <option value="">Select your major</option>
                <option value="Information Technology">
                  Information Technology
                </option>
                <option value="Business Administration">
                  Business Administration
                </option>
                <option value="Engineering">Engineering</option>
                <option value="Mass Communication">Mass Communication</option>
              </Input>
              <p className="error">{errors.major?.message}</p>
            </Col>
          </Row>

          <Row>
            <Col md={6}>
              <Label>Age</Label>
              <Input
                type="number"
                name="age"
                min="17"
                max="45"
                {...register("age", {
                  value: age,
                  onChange: (e) => setAge(e.target.value),
                })}
              />
              <p className="error">{errors.age?.message}</p>
            </Col>
          </Row>

          <Row>
            <Col md={6}>
              <Button className="reg-btn">Sign up</Button>
            </Col>
          </Row>

          <p className="login-text">
            Already have an account?{" "}
            <Link to="/login" className="login-link">
              Log in now!
            </Link>
          </p>
        </Form>
      </div>
    </Container>
  );
};

export default UserRegister;
